head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 1, 2, 3, 4번 각각 체크박스를 체크해본다.
    //1. Run the sample file and check the checkboxes 1, 2, 3 and 4 respectively.
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2checkbox_input')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2checkbox_input')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2checkbox_input')[2].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2checkbox_input')[3].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 체크박스가 정상적으로 1번, 2번, 3번, 4번 순서대로 체크되어진다. (이전에는 1번체크 후 2번체크시 체크되지 않고 1번체크된 부분이 풀려짐)
    //Check box is normally 1, 2, 3, 4 They are checked in order. (Previously, after checking 1, check 2 is not checked and checked 1 is released)
    WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('w2checkbox_input')[0].checked", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('w2checkbox_input')[1].checked", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('w2checkbox_input')[2].checked", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('w2checkbox_input')[3].checked", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 30-Jan-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
